func maskToSlice(mask uint16, card uint8) []int {
	out := make([]int, 0, card)
	for p := range 12 {
		if mask&(1<<p) != 0 {
			out = append(out, p)
		}
	}
	return out
}

func sliceToPrimeMask(numbers []int) (uint64, bool) {
	if len(numbers) == 0 {
		return 0, true
	}
	if numbers[0] != 0 {
		return 0, false
	}
	mask := uint64(1)
	prev := 0
	for i := 1; i < len(numbers); i++ {
		v := numbers[i]
		if v <= prev || v > 11 {
			return 0, false
		}
		mask |= 1 << uint(v)
		prev = v
	}
	return mask, true
}

func parseDecimalNoLeadingZero(part string) (int, bool) {
	if part == "" || (len(part) > 1 && part[0] == '0') {
		return 0, false
	}
	n := 0
	for i := range len(part) {
		ch := part[i]
		if ch < '0' || ch > '9' {
			return 0, false
		}
		n = min(n*10+int(ch-'0'), 1000)
	}
	return n, true
}

func parseForteComponents(s string, allowSuffix bool) (uint8, Suffix, error) {
	before, after, ok := strings.Cut(s, "-")
	if !ok {
		return 0, SuffixNone, fmt.Errorf("%w: %q", ErrInvalidNotation, s)
	}
	card, okCard := parseDecimalNoLeadingZero(before)
	hasZ := strings.HasPrefix(after, "Z")
	if hasZ {
		after = after[1:]
	}
	suffix := SuffixNone
	if strings.HasSuffix(after, "A") {
		suffix = SuffixA
		after = after[:len(after)-1]
	} else if strings.HasSuffix(after, "B") {
		suffix = SuffixB
		after = after[:len(after)-1]
	}
	ord, okOrd := parseDecimalNoLeadingZero(after)
	if !okCard || !okOrd || (!allowSuffix && suffix != SuffixNone) {
		return 0, SuffixNone, fmt.Errorf("%w: %q", ErrInvalidNotation, s)
	}
	if card > 12 {
		return 0, SuffixNone, fmt.Errorf("%w: %w: %q", ErrInvalidNotation, ErrInvalidCardinality, s)
	}
	if ord < 1 || ord > int(forteMaxOrdinal[card]) {
		return 0, SuffixNone, fmt.Errorf("%w: %w: %q", ErrInvalidNotation, ErrInvalidOrdinal, s)
	}
	fcIdx := forteCardStart[card] + uint8(ord-1)
	if forteTable[fcIdx].isZ != hasZ {
		return 0, SuffixNone, fmt.Errorf("%w: %q", ErrInvalidNotation, s)
	}
	return fcIdx, suffix, nil
}
